import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {ownershipCompiler} from '../js-to-rust/vendor/module-syntax.mjs';
import {proposeRuntimeImportCommonGuard} from '../prepare-runtime-import-common-guard.mjs';
import {transportConcreteSyntaxMeta} from '../concrete-syntax-meta.mjs';
import * as guards from '../original-json-intrinsics.mjs';

const sourcePath='tools/translation/js-to-rust/owned-core-source.mjs';
const original=gunzipSync(readFileSync(new URL('../source-profiles/runtime-import-common-guard/original.mjs.gz',import.meta.url)),{maxOutputLength:262144}).toString('utf8');
const legacy=()=>guards.originalPrivateParserIngressUnchanged()
 &&guards.originalNamespaceTraversalIntrinsicsUnchanged()
 &&guards.originalDataFreezeIntrinsicsUnchanged()
 &&guards.originalStaticSourceIntrinsicsUnchanged();
const common=()=>guards.originalPrivateParserCommonIntrinsicsUnchanged();
const descriptor=Object.getOwnPropertyDescriptor,define=Object.defineProperty,remove=Reflect.deleteProperty;

test('runtime import common guard source preserves both complete CST phases and original fresh fences',{timeout:60000},()=>{
 assert.equal(createHash('sha256').update(original).digest('hex'),'ebd45c97808dbe473fcbc77c1663bcd0168953dfa25e16c305878f5736e6d2d9');
 const ts=ownershipCompiler(),row=proposeRuntimeImportCommonGuard(ts,sourcePath,original);
 assert.equal(row.before,original);assert.equal(row.inverse,original);
 assert.equal(readFileSync(new URL('../js-to-rust/owned-core-source.mjs',import.meta.url),'utf8'),row.after);
 assert.deepEqual(row.rules.map(rule=>rule.phase),['language','language','repository']);
 assert.deepEqual(row.equation.stages.map(stage=>stage.phase),['language','repository']);
 for(const stage of row.equation.stages){
  assert.equal(stage.inverse,stage.before);
  assert.equal(transportConcreteSyntaxMeta(stage.beforeMeta).source,stage.before);
  assert.equal(transportConcreteSyntaxMeta(stage.afterMeta).source,stage.after);
 }
 let restored=row.after;
 for(const rule of [...row.rules].reverse())restored=restored.replace(rule.after,()=>rule.before);
 assert.equal(restored,original);
 assert.equal(row.originalFreshParsesRetained,true);assert.equal(row.originalSourceFencesRetained,true);
 assert.equal(row.retainedVerdicts,false);assert.equal(row.originalDeadlinesQualified,false);
 assert.equal(row.semanticAuthority,false);assert.equal(row.runtimeParity,false);
 assert.throws(()=>proposeRuntimeImportCommonGuard(ts,sourcePath,original+'\n'),/complete native predecessor differs/);
 assert.throws(()=>proposeRuntimeImportCommonGuard(ts,'foreign.mjs',original),/complete native predecessor differs/);
});

test('the actual runtime conjunction and common guard agree under descriptor and ingress changes without callbacks',{timeout:60000},()=>{
 assert.equal(legacy(),true);assert.equal(common(),true);
 let callbacks=0;
 const cases=[
  [String.prototype,'charCodeAt'],[WeakMap.prototype,'get'],
  [Map.prototype,'entries'],[Array.prototype,'find'],[globalThis,'Symbol'],
 ];
 for(const [owner,key]of cases){
  const field=descriptor(owner,key);let before,after;
  try{
   define(owner,key,{configurable:true,get(){callbacks++;return field.value;}});
   before=legacy();after=common();
  }finally{define(owner,key,field);}
  assert.equal(before,false,key);assert.equal(after,false,key);
  assert.equal(legacy(),true,key);assert.equal(common(),true,key);
 }
 for(const owner of [Object.prototype,Array.prototype,String.prototype]){
  const key='1234567',field=descriptor(owner,key),length=owner===Array.prototype?descriptor(owner,'length'):null;
  let before,after;
  try{
   define(owner,key,{configurable:true,get(){callbacks++;return 7;}});
   before=legacy();after=common();
  }finally{
   if(field)define(owner,key,field);else remove(owner,key);
   if(length)define(owner,'length',length);
  }
  assert.equal(before,false);assert.equal(after,false);
  assert.equal(legacy(),true);assert.equal(common(),true);
 }
 assert.equal(callbacks,0);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {prepareRuntimeImportCurrentSources} from '../prepare-runtime-import-current-sources.mjs';
import {transportConcreteSyntaxMeta} from '../concrete-syntax-meta.mjs';

test('current runtime-import consumers retain the complete historical producers and fresh reversible source equations',{timeout:60000},()=>{
 const plan=prepareRuntimeImportCurrentSources();
 assert.equal(plan.typescriptVersion,'5.9.3');
 assert.equal(plan.files.length,12);
 assert.equal(new Set(plan.files.map(row=>row.path)).size,12);
 assert.equal(plan.originalPublicPreparationUnchanged,true);
 assert.equal(plan.originalRuntimeIssuersUnchanged,true);
 assert.equal(plan.semanticAuthority,false);
 assert.equal(plan.runtimeParity,false);
 const root=new URL('../../../',import.meta.url),read=path=>readFileSync(new URL(path,root),'utf8');
 assert.equal(read(plan.originalProducer.path),plan.originalProducer.after);
 assert.equal(read(plan.originalNodeHelper.path),plan.originalNodeHelper.source);
 for(const row of plan.files){
  assert.equal(read(row.path),row.after,row.path);
  assert.equal(row.current,row.after,row.path);
  assert.equal(row.equation.inverse,row.before,row.path);
  assert.equal(row.nativeBindings.nativeSemanticScopeChecked,true,row.path);
  const historyAfter=row.commonGuardPreviousAfter??row.after;
  if(Object.hasOwn(row,'bindingBatch')){
   assert.equal(row.bindingBatch.before,row.bindingPreviousAfter,row.path);
   assert.equal(row.bindingBatch.after,row.commonGuardPreviousAfter??row.after,row.path);assert.equal(row.bindingBatch.inverse,row.bindingPreviousAfter,row.path);
   assert.equal(row.bindingBatch.semanticAuthority,false);assert.equal(row.bindingBatch.runtimeAuthority,false);
   assert.equal(row.bindingPreviousEquation.before,row.bindingPreviousAfter,row.path);
   assert.equal(row.bindingPreviousEquation.after,historyAfter,row.path);assert.equal(row.bindingPreviousEquation.inverse,row.bindingPreviousAfter,row.path);
   for(const stage of row.bindingPreviousEquation.stages){assert.equal(transportConcreteSyntaxMeta(stage.beforeMeta).source,stage.before,row.path);assert.equal(transportConcreteSyntaxMeta(stage.afterMeta).source,stage.after,row.path);}
  }
  if(Object.hasOwn(row,'commonGuardPreviousAfter')){
   assert.equal(row.commonGuardPreviousEquation.before,row.commonGuardPreviousAfter,row.path);
   assert.equal(row.commonGuardPreviousEquation.after,row.after,row.path);
   assert.equal(row.commonGuardPreviousEquation.inverse,row.commonGuardPreviousAfter,row.path);
   for(const stage of row.commonGuardPreviousEquation.stages){assert.equal(transportConcreteSyntaxMeta(stage.beforeMeta).source,stage.before,row.path);assert.equal(transportConcreteSyntaxMeta(stage.afterMeta).source,stage.after,row.path);}
  }
  if(Object.hasOwn(row,'runtimePreviousAfter')){
   assert.equal(row.runtimePreviousEquation.before,row.runtimePreviousAfter,row.path);
   assert.equal(row.runtimePreviousEquation.after,historyAfter,row.path);assert.equal(row.runtimePreviousEquation.inverse,row.runtimePreviousAfter,row.path);
  }
  if(Object.hasOwn(row,'lifetimeAfter')){
   assert.equal(row.lifetimeEquation.before,row.lifetimeAfter,row.path);assert.equal(row.lifetimeEquation.after,historyAfter,row.path);assert.equal(row.lifetimeEquation.inverse,row.lifetimeAfter,row.path);
   for(const stage of row.lifetimeEquation.stages){assert.equal(transportConcreteSyntaxMeta(stage.beforeMeta).source,stage.before,row.path);assert.equal(transportConcreteSyntaxMeta(stage.afterMeta).source,stage.after,row.path);}
  }
  assert.deepEqual(row.equation.stages.map(stage=>stage.phase),['language','repository']);
  for(const stage of row.equation.stages){
   assert.equal(stage.inverse,stage.before,row.path);
   assert.equal(transportConcreteSyntaxMeta(stage.beforeMeta).source,stage.before,row.path);
   assert.equal(transportConcreteSyntaxMeta(stage.afterMeta).source,stage.after,row.path);
  }
 }
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {ownershipCompiler} from '../js-to-rust/vendor/module-syntax.mjs';
import {verifyNativeCopiedSourceBindings} from '../source-copy-native-bindings.mjs';
test('native source-copy scope validation joins actual import bindings and rejects omitted imports', {timeout:60_000},()=>{
 const ts=ownershipCompiler(),source="import {posix} from 'node:path';export const value=posix.normalize('src/app.rs');";
 assert.deepEqual(verifyNativeCopiedSourceBindings(ts,'/private/tmp/copied-formatting-source.mjs',source).unboundIdentifiers,[]);
 assert.throws(()=>verifyNativeCopiedSourceBindings(ts,'/private/tmp/copied-formatting-source.mjs',source.replace("import {posix} from 'node:path';",'')),/unbound identifier.*posix/);
 assert.throws(()=>verifyNativeCopiedSourceBindings(ts,'/private/tmp/copied-formatting-source.mjs','export const value={missing};'),/unbound identifier/);
 assert.equal(verifyNativeCopiedSourceBindings(ts,'/private/tmp/copied-formatting-source.mjs','export const value=process.pid+Buffer.byteLength("ok");').strictTypecheck,false);
});
test('native source-copy validation rejects the actual URL initialization shadow and preserves deferred bindings', {timeout:60_000},()=>{
 const ts=ownershipCompiler(),path='/private/tmp/copied-formatting-source.mjs';
 const source="import {fileURLToPath} from 'node:url';const ROOT=fileURLToPath(new URL('../',import.meta.url)),URL=new globalThis.URL('./subject.mjs',import.meta.url);export {ROOT,URL};";
 assert.throws(()=>verifyNativeCopiedSourceBindings(ts,path,source),/initialization.*URL.*before its declaration/);
 const repaired=source.replace(',URL=new globalThis.URL',',subjectURL=new globalThis.URL').replace('{ROOT,URL}','{ROOT,subjectURL}');
 assert.equal(verifyNativeCopiedSourceBindings(ts,path,repaired).nativeSemanticScopeChecked,true);
 for(const legal of [
  'export const deferred=()=>later;const later=1;',
  'export function deferred(){return later;}const later=1;',
  'export const value=hoisted();function hoisted(){return 1;}',
 ])assert.equal(verifyNativeCopiedSourceBindings(ts,path,legal).strictTypecheck,false);
});
